  "marketplace.photo.label": { id: "Foto Barang", en: "Item Photos", ms: "Foto Barang", th: "รูปสินค้า", fil: "Mga Larawan ng Item", vi: "Ảnh sản phẩm" },
  "marketplace.photo.alt": { id: "Foto", en: "Photo", ms: "Foto", th: "รูป", fil: "Larawan", vi: "Ảnh" },
