  "marketplace.photo.makeMain": { id: "Jadikan utama", en: "Make main", ms: "Jadikan utama", th: "ตั้งเป็นรูปหลัก", fil: "Gawing pangunahin", vi: "Đặt làm ảnh chính" },
  "marketplace.photo.remove": { id: "Hapus foto", en: "Remove photo", ms: "Buang foto", th: "ลบรูป", fil: "Alisin ang larawan", vi: "Xóa ảnh" },
  "marketplace.uploading": { id: "Mengunggah...", en: "Uploading...", ms: "Memuat naik...", th: "กำลังอัปโหลด...", fil: "Ina-upload...", vi: "Đang tải lên..." },
  "marketplace.photo.add": { id: "Tambah Foto", en: "Add Photo", ms: "Tambah Foto", th: "เพิ่มรูป", fil: "Magdagdag ng Larawan", vi: "Thêm ảnh" },
  "marketplace.photo.hint": { id: "Maksimal {max} foto (JPG/PNG/WEBP). Foto pertama jadi foto utama di etalase. Tunjukkan kondisi asli: depan, belakang, bagian yang lecet, dan kelengkapan.", en: "Maximum {max} photos (JPG/PNG/WEBP). The first photo becomes the main photo in the showcase. Show the real condition: front, back, scuffed areas, and included items.", ms: "Maksimum {max} foto (JPG/PNG/WEBP). Foto pertama menjadi foto utama di etalase. Tunjukkan keadaan sebenar: depan, belakang, bahagian yang calar, dan kelengkapan.", th: "สูงสุด {max} รูป (JPG/PNG/WEBP) รูปแรกจะเป็นรูปหลักในหน้าร้าน แสดงสภาพจริง: ด้านหน้า ด้านหลัง จุดที่มีรอย และอุปกรณ์ที่มีให้", fil: "Hanggang {max} larawan (JPG/PNG/WEBP). Ang unang larawan ang magiging pangunahin sa showcase. Ipakita ang tunay na kondisyon: harap, likod, mga gasgas, at mga kasama.", vi: "Tối đa {max} ảnh (JPG/PNG/WEBP). Ảnh đầu tiên là ảnh chính trên gian hàng. Thể hiện tình trạng thật: mặt trước, mặt sau, chỗ trầy xước và phụ kiện kèm theo." },
  "marketplace.photo.prev": { id: "Foto sebelumnya", en: "Previous photo", ms: "Foto sebelumnya", th: "รูปก่อนหน้า", fil: "Nakaraang larawan", vi: "Ảnh trước" },
  "marketplace.photo.next": { id: "Foto berikutnya", en: "Next photo", ms: "Foto seterusnya", th: "รูปถัดไป", fil: "Susunod na larawan", vi: "Ảnh tiếp" },
