  "marketplace.allCategories": { id: "Semua kategori", en: "All categories", ms: "Semua kategori", th: "ทุกหมวดหมู่", fil: "Lahat ng kategorya", vi: "Tất cả danh mục" },
  "marketplace.showcaseEmpty": { id: "Belum ada barang dari outlet lain. Coba lagi nanti, atau pasang barang Anda sendiri di tab Barang Saya.", en: "No items from other outlets yet. Try again later, or list your own items in the My Items tab.", ms: "Belum ada barang daripada outlet lain. Cuba lagi nanti, atau pasang barang anda sendiri di tab Barang Saya.", th: "ยังไม่มีสินค้าจากสาขาอื่น ลองใหม่ภายหลัง หรือลงขายสินค้าของคุณในแท็บสินค้าของฉัน", fil: "Wala pang item mula sa ibang outlet. Subukan ulit mamaya, o ilista ang sarili mong item sa tab na Mga Item Ko.", vi: "Chưa có hàng từ cửa hàng khác. Thử lại sau, hoặc đăng hàng của bạn ở tab Hàng của tôi." },
  "marketplace.availableUnits": { id: "Tersedia {n} unit", en: "{n} units available", ms: "{n} unit tersedia", th: "มี {n} หน่วย", fil: "{n} unit ang available", vi: "Còn {n} chiếc" },
  "marketplace.negotiable": { id: "Bisa nego", en: "Negotiable", ms: "Boleh runding", th: "ต่อรองได้", fil: "Puwedeng tawaran", vi: "Có thương lượng" },
  "marketplace.fixedPrice": { id: "Harga pas", en: "Fixed price", ms: "Harga tetap", th: "ราคาตายตัว", fil: "Fixed na presyo", vi: "Giá cố định" },
  "marketplace.requestBuy": { id: "Ajukan Beli", en: "Request to Buy", ms: "Mohon Beli", th: "ขอซื้อ", fil: "Humiling Bumili", vi: "Yêu cầu mua" },
  "marketplace.offer.phoneRequired": { id: "Isi No. HP Anda — penjual akan menghubungi nomor ini setelah menerima penawaran.", en: "Enter your phone number — the seller will contact this number after accepting the offer.", ms: "Isi nombor telefon anda — penjual akan menghubungi nombor ini selepas menerima tawaran.", th: "กรอกเบอร์โทรของคุณ — ผู้ขายจะติดต่อเบอร์นี้หลังตอบรับข้อเสนอ", fil: "Ilagay ang numero ng telepono mo — tatawagan ka ng nagbebenta sa numerong ito kapag tinanggap ang alok.", vi: "Nhập số điện thoại của bạn — người bán sẽ liên hệ số này sau khi chấp nhận đề nghị." },
  "marketplace.offer.sent": { id: "Penawaran {no} terkirim. Setelah penjual menerimanya, nomor HP kedua pihak muncul di tab Kesepakatan.", en: "Offer {no} sent. Once the seller accepts it, both parties' phone numbers appear in the Deals tab.", ms: "Tawaran {no} dihantar. Selepas penjual menerimanya, nombor telefon kedua-dua pihak muncul di tab Perjanjian.", th: "ส่งข้อเสนอ {no} แล้ว เมื่อผู้ขายตอบรับ เบอร์โทรของทั้งสองฝ่ายจะแสดงในแท็บข้อตกลง", fil: "Naipadala ang alok {no}. Kapag tinanggap ng nagbebenta, lalabas ang numero ng dalawang panig sa tab na Mga Kasunduan.", vi: "Đã gửi đề nghị {no}. Khi người bán chấp nhận, số điện thoại của hai bên sẽ hiện ở tab Giao dịch." },
  "marketplace.offer.fromSeller": { id: "Dari {outlet}. Harga pasang {price}", en: "From {outlet}. Listed price {price}", ms: "Daripada {outlet}. Harga dipasang {price}", th: "จาก {outlet} ราคาที่ลงไว้ {price}", fil: "Mula sa {outlet}. Nakalistang presyo {price}", vi: "Từ {outlet}. Giá niêm yết {price}" },
  "marketplace.negotiableLower": { id: "bisa nego", en: "negotiable", ms: "boleh runding", th: "ต่อรองได้", fil: "puwedeng tawaran", vi: "có thương lượng" },
  "marketplace.fixedPriceLower": { id: "harga pas", en: "fixed price", ms: "harga tetap", th: "ราคาตายตัว", fil: "fixed na presyo", vi: "giá cố định" },
  "marketplace.offer.cautionTitle": { id: "Perhatikan sebelum menawar", en: "Take note before making an offer", ms: "Perhatikan sebelum menawar", th: "โปรดพิจารณาก่อนยื่นข้อเสนอ", fil: "Pansinin bago mag-alok", vi: "Lưu ý trước khi trả giá" },
  "marketplace.offer.cautionHint": { id: "Sarankan bertemu langsung (COD) atau bayar setelah barang terlihat.", en: "We suggest meeting in person (COD) or paying after you've seen the item.", ms: "Disarankan bertemu bersemuka (COD) atau bayar selepas barang dilihat.", th: "แนะนำให้นัดเจอตัวจริง (COD) หรือจ่ายหลังเห็นสินค้าแล้ว", fil: "Inirerekomendang magkita nang personal (COD) o magbayad pagkatapos makita ang item.", vi: "Nên gặp trực tiếp (COD) hoặc trả tiền sau khi đã thấy hàng." },
