  "marketplace.offer.phoneHint": { id: "Baru terlihat oleh penjual setelah ia menerima penawaran Anda.", en: "Only visible to the seller after they accept your offer.", ms: "Hanya kelihatan kepada penjual selepas dia menerima tawaran anda.", th: "ผู้ขายจะเห็นหลังจากตอบรับข้อเสนอของคุณเท่านั้น", fil: "Makikita lang ng nagbebenta kapag tinanggap na niya ang alok mo.", vi: "Người bán chỉ thấy sau khi chấp nhận đề nghị của bạn." },
  "marketplace.offer.total": { id: "Total yang Anda bayar ke penjual", en: "Total you pay to the seller", ms: "Jumlah yang anda bayar kepada penjual", th: "ยอดรวมที่คุณจ่ายให้ผู้ขาย", fil: "Kabuuang babayaran mo sa nagbebenta", vi: "Tổng số bạn trả cho người bán" },
  "marketplace.offer.directPayment": { id: "Pembayaran dilakukan langsung ke outlet penjual (transfer atau bayar di tempat). NEXBILL tidak menahan dana dan tidak menjadi perantara pembayaran.", en: "Payment is made directly to the seller's outlet (transfer or pay on the spot). NEXBILL does not hold funds and is not a payment intermediary.", ms: "Bayaran dibuat terus kepada outlet penjual (pindahan atau bayar di tempat). NEXBILL tidak menahan dana dan bukan perantara pembayaran.", th: "ชำระเงินโดยตรงกับสาขาผู้ขาย (โอนหรือจ่ายที่นั่น) NEXBILL ไม่ถือเงินและไม่ใช่ตัวกลางการชำระเงิน", fil: "Direktang nagbabayad sa outlet ng nagbebenta (transfer o bayad sa lugar). Hindi humahawak ng pera ang NEXBILL at hindi ito tagapamagitan sa bayad.", vi: "Thanh toán trực tiếp cho cửa hàng người bán (chuyển khoản hoặc trả tại chỗ). NEXBILL không giữ tiền và không làm trung gian thanh toán." },
  "marketplace.sending": { id: "Mengirim...", en: "Sending...", ms: "Menghantar...", th: "กำลังส่ง...", fil: "Ipinapadala...", vi: "Đang gửi..." },
