  "marketplace.listing.nameRequired": { id: "Nama barang wajib diisi.", en: "Item name is required.", ms: "Nama barang wajib diisi.", th: "ต้องระบุชื่อสินค้า", fil: "Kailangan ang pangalan ng item.", vi: "Bắt buộc nhập tên hàng." },
  "marketplace.listing.priceRequired": { id: "Harga harus lebih dari 0.", en: "Price must be greater than 0.", ms: "Harga mesti lebih daripada 0.", th: "ราคาต้องมากกว่า 0", fil: "Dapat higit sa 0 ang presyo.", vi: "Giá phải lớn hơn 0." },
  "marketplace.listing.phoneRequired": { id: "Isi No. HP — pembeli akan menghubungi nomor ini setelah Anda menerima penawarannya.", en: "Enter a phone number — buyers will contact this number after you accept their offer.", ms: "Isi nombor telefon — pembeli akan menghubungi nombor ini selepas anda menerima tawarannya.", th: "กรอกเบอร์โทร — ผู้ซื้อจะติดต่อเบอร์นี้หลังคุณตอบรับข้อเสนอ", fil: "Ilagay ang numero ng telepono — tatawagan ka ng mamimili sa numerong ito kapag tinanggap mo ang alok niya.", vi: "Nhập số điện thoại — người mua sẽ liên hệ số này sau khi bạn chấp nhận đề nghị của họ." },
  "marketplace.listing.waitPhotos": { id: "Tunggu sampai semua foto selesai diunggah.", en: "Wait until all photos have finished uploading.", ms: "Tunggu sehingga semua foto selesai dimuat naik.", th: "รอจนอัปโหลดรูปทั้งหมดเสร็จ", fil: "Hintaying matapos ma-upload ang lahat ng larawan.", vi: "Chờ đến khi tải xong tất cả ảnh." },
  "marketplace.listing.confirmNoPhoto": { id: "Pasang barang tanpa foto? Barang dengan foto jauh lebih dipercaya dan lebih cepat laku.", en: "List the item without photos? Items with photos are trusted far more and sell faster.", ms: "Pasang barang tanpa foto? Barang dengan foto jauh lebih dipercayai dan lebih cepat laku.", th: "ลงขายโดยไม่มีรูปใช่ไหม? สินค้าที่มีรูปน่าเชื่อถือกว่ามากและขายได้เร็วกว่า", fil: "Ilista ang item nang walang larawan? Mas pinagkakatiwalaan at mas mabilis mabenta ang item na may larawan.", vi: "Đăng hàng không có ảnh? Hàng có ảnh đáng tin hơn nhiều và bán nhanh hơn." },
  "marketplace.listing.title": { id: "Pasang Barang", en: "List an Item", ms: "Pasang Barang", th: "ลงขายสินค้า", fil: "Maglista ng Item", vi: "Đăng bán hàng" },
  "marketplace.listing.newOutletLimit": { id: "Outlet Anda masih berstatus Outlet Baru di Marketplace, jadi nilai satu barang (harga × jumlah) dibatasi maksimal {max}. Batas ini terbuka otomatis setelah akun NEXBILL outlet berumur {days} hari — perlindungan bagi pembeli dari akun yang belum punya riwayat.", en: "Your outlet still has New Outlet status in the Marketplace, so the value of one item (price × quantity) is capped at {max}. This limit lifts automatically once the outlet's NEXBILL account is {days} days old — protection for buyers from accounts with no history.", ms: "Outlet anda masih berstatus Outlet Baharu di Marketplace, jadi nilai satu barang (harga × kuantiti) dihadkan maksimum {max}. Had ini dibuka secara automatik selepas akaun NEXBILL outlet berumur {days} hari — perlindungan bagi pembeli daripada akaun yang belum ada rekod.", th: "สาขาของคุณยังมีสถานะสาขาใหม่ใน Marketplace มูลค่าสินค้าหนึ่งรายการ (ราคา × จำนวน) จึงจำกัดไม่เกิน {max} ข้อจำกัดนี้จะปลดอัตโนมัติเมื่อบัญชี NEXBILL ของสาขามีอายุ {days} วัน — เพื่อปกป้องผู้ซื้อจากบัญชีที่ยังไม่มีประวัติ", fil: "Bagong Outlet pa ang status ng outlet mo sa Marketplace, kaya ang halaga ng isang item (presyo × dami) ay hanggang {max} lang. Kusang aalisin ang limitasyong ito kapag {days} araw na ang NEXBILL account ng outlet — proteksyon ng mamimili laban sa account na walang kasaysayan.", vi: "Cửa hàng của bạn vẫn ở trạng thái Cửa hàng mới trên Marketplace, nên giá trị một món (giá × số lượng) bị giới hạn tối đa {max}. Giới hạn tự động được gỡ khi tài khoản NEXBILL của cửa hàng đủ {days} ngày — bảo vệ người mua khỏi tài khoản chưa có lịch sử." },
  "marketplace.listing.overLimit": { id: "Nilai barang ini melebihi batas outlet baru — kurangi harga atau jumlahnya.", en: "This item's value exceeds the new-outlet limit — lower the price or quantity.", ms: "Nilai barang ini melebihi had outlet baharu — kurangkan harga atau kuantitinya.", th: "มูลค่าสินค้านี้เกินขีดจำกัดของสาขาใหม่ — ลดราคาหรือจำนวนลง", fil: "Lampas sa limitasyon ng bagong outlet ang halaga ng item na ito — bawasan ang presyo o dami.", vi: "Giá trị món này vượt giới hạn cửa hàng mới — hãy giảm giá hoặc số lượng." },
