  "marketplace.optionalParen": { id: "(opsional)", en: "(optional)", ms: "(pilihan)", th: "(ไม่บังคับ)", fil: "(opsyonal)", vi: "(tùy chọn)" },
  "marketplace.withdrawForm.submit": { id: "Tarik Barang", en: "Withdraw Item", ms: "Tarik Barang", th: "ถอนสินค้า", fil: "Bawiin ang Item", vi: "Gỡ hàng" },
  "marketplace.deal.confirmAccept": { id: "Terima penawaran {no}? Dengan menerima, Anda berjanji menyerahkan barang sesuai foto & keterangan. Nomor HP dan rekening penerima Anda akan terlihat oleh pembeli, dan rekeningnya DIKUNCI ke kesepakatan ini. Serahkan barang setelah pembayaran benar-benar masuk (cek mutasi rekening, bukan hanya foto bukti transfer).", en: "Accept offer {no}? By accepting, you promise to hand over the item as shown in the photos & description. Your phone number and payout account will be visible to the buyer, and the account is LOCKED to this deal. Hand over the item only after the payment has really arrived (check your bank statement, not just a transfer screenshot).", ms: "Terima tawaran {no}? Dengan menerima, anda berjanji menyerahkan barang mengikut foto & keterangan. Nombor telefon dan akaun penerima anda akan kelihatan kepada pembeli, dan akaunnya DIKUNCI kepada perjanjian ini. Serahkan barang selepas bayaran benar-benar masuk (semak penyata bank, bukan hanya foto bukti pindahan).", th: "ตอบรับข้อเสนอ {no} ใช่ไหม? เมื่อตอบรับ คุณสัญญาว่าจะส่งมอบสินค้าตามรูปและคำอธิบาย เบอร์โทรและบัญชีรับเงินของคุณจะแสดงให้ผู้ซื้อเห็น และบัญชีจะถูกล็อกกับข้อตกลงนี้ ส่งมอบสินค้าหลังเงินเข้าจริงแล้วเท่านั้น (ตรวจรายการเดินบัญชี ไม่ใช่แค่ภาพสลิปโอน)", fil: "Tanggapin ang alok {no}? Sa pagtanggap, nangangako kang iaabot ang item ayon sa larawan at paglalarawan. Makikita ng mamimili ang numero mo at ang account na tatanggap ng bayad, at NAKA-LOCK ang account sa kasunduang ito. Iabot ang item kapag talagang pumasok na ang bayad (suriin ang bank statement, hindi lang ang larawan ng transfer).", vi: "Chấp nhận đề nghị {no}? Khi chấp nhận, bạn cam kết giao hàng đúng như ảnh & mô tả. Số điện thoại và tài khoản nhận tiền của bạn sẽ hiển thị cho người mua, và tài khoản bị KHÓA vào giao dịch này. Chỉ giao hàng khi tiền đã thực sự vào (kiểm tra sao kê, không chỉ ảnh chụp chuyển khoản)." },
  "marketplace.deal.confirmComplete": { id: "Tandai {no} selesai? Ini berarti barangnya sudah Anda terima DAN sudah Anda bayar ke penjual. Penjual akan otomatis mencatat pendapatannya. Jika ada masalah, jangan tandai selesai — gunakan \"Laporkan Masalah\".", en: "Mark {no} as completed? This means you have received the item AND paid the seller. The seller will record the revenue automatically. If there's a problem, don't mark it completed — use \"Report a Problem\".", ms: "Tandakan {no} selesai? Ini bermaksud anda sudah menerima barang DAN sudah membayar penjual. Penjual akan merekod hasilnya secara automatik. Jika ada masalah, jangan tandakan selesai — gunakan \"Laporkan Masalah\".", th: "ทำเครื่องหมาย {no} ว่าเสร็จสิ้นใช่ไหม? หมายความว่าคุณได้รับสินค้าแล้วและจ่ายเงินให้ผู้ขายแล้ว ผู้ขายจะบันทึกรายได้อัตโนมัติ หากมีปัญหา อย่าทำเครื่องหมายว่าเสร็จ — ใช้ \"รายงานปัญหา\"", fil: "Markahan ang {no} bilang tapos? Ibig sabihin nito natanggap mo na ang item AT nabayaran mo na ang nagbebenta. Awtomatikong itatala ng nagbebenta ang kita. Kung may problema, huwag markahang tapos — gamitin ang \"Mag-ulat ng Problema\".", vi: "Đánh dấu {no} là hoàn tất? Nghĩa là bạn đã nhận hàng VÀ đã trả tiền cho người bán. Người bán sẽ tự động ghi nhận doanh thu. Nếu có vấn đề, đừng đánh dấu hoàn tất — hãy dùng \"Báo cáo sự cố\"." },
  "marketplace.deal.rejectReasonPrompt": { id: "alasan menolak penawaran?", en: "reason for rejecting the offer?", ms: "sebab menolak tawaran?", th: "เหตุผลที่ปฏิเสธข้อเสนอ?", fil: "dahilan ng pagtanggi sa alok?", vi: "lý do từ chối đề nghị?" },
  "marketplace.deal.cancelReasonPrompt": { id: "alasan membatalkan kesepakatan?", en: "reason for cancelling the deal?", ms: "sebab membatalkan perjanjian?", th: "เหตุผลที่ยกเลิกข้อตกลง?", fil: "dahilan ng pagkansela sa kasunduan?", vi: "lý do hủy giao dịch?" },
  "marketplace.deal.rejectTitle": { id: "Tolak penawaran", en: "Reject offer", ms: "Tolak tawaran", th: "ปฏิเสธข้อเสนอ", fil: "Tanggihan ang alok", vi: "Từ chối đề nghị" },
  "marketplace.deal.cancelTitle": { id: "Batalkan kesepakatan", en: "Cancel deal", ms: "Batalkan perjanjian", th: "ยกเลิกข้อตกลง", fil: "Kanselahin ang kasunduan", vi: "Hủy giao dịch" },
  "marketplace.deal.reasonPlaceholder": { id: "Alasan ini terbaca oleh pihak lawan. Jangan tulis nomor HP/kontak.", en: "The other party can read this reason. Don't write phone numbers/contacts.", ms: "Sebab ini boleh dibaca pihak lawan. Jangan tulis nombor telefon/kenalan.", th: "อีกฝ่ายจะอ่านเหตุผลนี้ได้ อย่าเขียนเบอร์โทร/ช่องทางติดต่อ", fil: "Mababasa ito ng kabilang panig. Huwag isulat ang numero/contact.", vi: "Bên kia sẽ đọc được lý do này. Đừng ghi số điện thoại/liên hệ." },
  "marketplace.deal.reject": { id: "Tolak", en: "Reject", ms: "Tolak", th: "ปฏิเสธ", fil: "Tanggihan", vi: "Từ chối" },
