  "marketplace.deal.phonesAfterAccept": { id: "Nomor HP kedua pihak dibuka setelah penjual menerima penawaran.", en: "Both parties' phone numbers are revealed after the seller accepts the offer.", ms: "Nombor telefon kedua-dua pihak dibuka selepas penjual menerima tawaran.", th: "เบอร์โทรของทั้งสองฝ่ายจะเปิดเผยหลังผู้ขายตอบรับข้อเสนอ", fil: "Ipapakita ang numero ng dalawang panig kapag tinanggap ng nagbebenta ang alok.", vi: "Số điện thoại hai bên được hiển thị sau khi người bán chấp nhận đề nghị." },
  "marketplace.deal.feeInvoiced": { id: "(sudah ditagih)", en: "(already invoiced)", ms: "(sudah ditagih)", th: "(เรียกเก็บแล้ว)", fil: "(nasingil na)", vi: "(đã lập hóa đơn)" },
  "marketplace.deal.buyerPhone": { id: "No. HP pembeli", en: "Buyer's phone", ms: "No. telefon pembeli", th: "เบอร์โทรผู้ซื้อ", fil: "Numero ng mamimili", vi: "SĐT người mua" },
  "marketplace.deal.sellerPhone": { id: "No. HP penjual", en: "Seller's phone", ms: "No. telefon penjual", th: "เบอร์โทรผู้ขาย", fil: "Numero ng nagbebenta", vi: "SĐT người bán" },
  "marketplace.deal.chatWhatsapp": { id: "Chat WhatsApp", en: "Chat on WhatsApp", ms: "Chat WhatsApp", th: "แชท WhatsApp", fil: "Mag-chat sa WhatsApp", vi: "Chat WhatsApp" },
  "marketplace.deal.buyerNextStep": { id: "Setelah barang diterima dan dibayar, tekan \"Barang Diterima & Sudah Dibayar\" di bawah.", en: "Once the item is received and paid for, press \"Item Received & Paid\" below.", ms: "Selepas barang diterima dan dibayar, tekan \"Barang Diterima & Sudah Dibayar\" di bawah.", th: "เมื่อได้รับสินค้าและจ่ายเงินแล้ว ให้กด \"ได้รับสินค้าและจ่ายเงินแล้ว\" ด้านล่าง", fil: "Kapag natanggap at nabayaran na ang item, pindutin ang \"Natanggap ang Item at Bayad Na\" sa ibaba.", vi: "Sau khi đã nhận hàng và trả tiền, bấm \"Đã nhận hàng & đã thanh toán\" bên dưới." },
  "marketplace.deal.sellerNextStep": { id: "Atur serah-terima dan pembayaran dengan pembeli. Pembeli yang menandai selesai setelah barang diterima.", en: "Arrange the handover and payment with the buyer. The buyer marks it completed after receiving the item.", ms: "Atur serahan dan bayaran dengan pembeli. Pembeli yang menandakan selesai selepas barang diterima.", th: "นัดส่งมอบและชำระเงินกับผู้ซื้อ ผู้ซื้อจะทำเครื่องหมายว่าเสร็จหลังได้รับสินค้า", fil: "Isaayos ang pag-abot at bayad kasama ang mamimili. Ang mamimili ang magmamarka ng tapos pagkatanggap ng item.", vi: "Sắp xếp giao hàng và thanh toán với người mua. Người mua sẽ đánh dấu hoàn tất sau khi nhận hàng." },
  "marketplace.deal.recordPurchase": { id: "Jangan lupa catat pembelian ini di pembukuan Anda lewat menu Expense. Sistem tidak mencatatnya sendiri karena hanya Anda yang tahu barang ini dipakai sebagai persediaan, aset tetap, atau perlengkapan — dan akunnya berbeda untuk masing-masing.", en: "Don't forget to record this purchase in your books via the Expense menu. The system doesn't record it by itself because only you know whether the item is used as inventory, a fixed asset, or supplies — and each uses a different account.", ms: "Jangan lupa rekod belian ini dalam pembukuan anda melalui menu Perbelanjaan. Sistem tidak merekodnya sendiri kerana hanya anda yang tahu barang ini digunakan sebagai inventori, aset tetap, atau kelengkapan — dan akaunnya berbeza bagi setiap satu.", th: "อย่าลืมบันทึกการซื้อนี้ในบัญชีของคุณผ่านเมนูค่าใช้จ่าย ระบบไม่บันทึกเองเพราะมีเพียงคุณที่รู้ว่าสินค้านี้ใช้เป็นสินค้าคงคลัง สินทรัพย์ถาวร หรือวัสดุสิ้นเปลือง — ซึ่งใช้บัญชีต่างกัน", fil: "Huwag kalimutang itala ang pagbiling ito sa libro mo sa menu na Expense. Hindi ito kusang itinatala ng sistema dahil ikaw lang ang nakakaalam kung imbentaryo, fixed asset, o supplies ang item — at magkaiba ang account ng bawat isa.", vi: "Đừng quên ghi giao dịch mua này vào sổ sách qua menu Chi phí. Hệ thống không tự ghi vì chỉ bạn biết món này dùng làm hàng tồn kho, tài sản cố định hay vật tư — và mỗi loại dùng tài khoản khác nhau." },
  "marketplace.deal.accept": { id: "Terima Penawaran", en: "Accept Offer", ms: "Terima Tawaran", th: "ตอบรับข้อเสนอ", fil: "Tanggapin ang Alok", vi: "Chấp nhận đề nghị" },
