  "marketplace.dispute.sendResponse": { id: "Kirim Tanggapan", en: "Send Response", ms: "Hantar Maklum Balas", th: "ส่งคำชี้แจง", fil: "Ipadala ang Tugon", vi: "Gửi phản hồi" },
