  "marketplace.dispute.youWereReported": { id: "Anda dilaporkan", en: "You were reported", ms: "Anda dilaporkan", th: "คุณถูกร้องเรียน", fil: "Inireklamo ka", vi: "Bạn bị báo cáo" },
  "marketplace.dispute.respondentStatement": { id: "Tanggapan pihak terlapor", en: "Reported party's response", ms: "Maklum balas pihak yang dilaporkan", th: "คำชี้แจงของฝ่ายที่ถูกร้องเรียน", fil: "Tugon ng inireklamong panig", vi: "Phản hồi của bên bị báo cáo" },
  "marketplace.dispute.decision": { id: "Keputusan NEXBILL:", en: "NEXBILL decision:", ms: "Keputusan NEXBILL:", th: "คำตัดสินของ NEXBILL:", fil: "Pasya ng NEXBILL:", vi: "Quyết định của NEXBILL:" },
  "marketplace.dispute.reportedHint": { id: "Outlet lain melaporkan kesepakatan ini. Berikan tanggapan dan bukti Anda — aduan diputuskan setelah tim NEXBILL membaca kedua sisi.", en: "Another outlet reported this deal. Give your response and evidence — the report is decided after the NEXBILL team reads both sides.", ms: "Outlet lain melaporkan perjanjian ini. Berikan maklum balas dan bukti anda — aduan diputuskan selepas pasukan NEXBILL membaca kedua-dua pihak.", th: "สาขาอื่นร้องเรียนข้อตกลงนี้ ให้คำชี้แจงและหลักฐานของคุณ — ข้อร้องเรียนจะถูกตัดสินหลังทีม NEXBILL อ่านทั้งสองฝ่าย", fil: "May ibang outlet na nag-ulat sa kasunduang ito. Ibigay ang tugon at patunay mo — pagpapasyahan ang reklamo pagkatapos basahin ng NEXBILL team ang dalawang panig.", vi: "Một cửa hàng khác đã báo cáo giao dịch này. Hãy gửi phản hồi và chứng cứ — khiếu nại được quyết định sau khi đội NEXBILL đọc cả hai phía." },
